using System.Net;using System.Net.Http.Headers;using System.Text;using System.Xml.Linq;namespace MeshDriveSync;
public sealed class WebDavClient:IDisposable{readonly HttpClient http;readonly Uri root;public WebDavClient(AppSettings s,string pass){root=new Uri(s.ServerUrl.EndsWith('/')?s.ServerUrl:s.ServerUrl+"/");http=new HttpClient(){Timeout=TimeSpan.FromMinutes(5)};http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes($"{s.Username}:{pass}")));}Uri Url(string p,bool file=false){p=p.Replace('\\','/').Trim('/');return new Uri(root,string.Join('/',p.Split('/',StringSplitOptions.RemoveEmptyEntries).Select(Uri.EscapeDataString))+(!file&&p.Length>0?"/":""));}async Task<XDocument> Prop(string p,string depth,CancellationToken ct){using var q=new HttpRequestMessage(new HttpMethod("PROPFIND"),Url(p));q.Headers.Add("Depth",depth);q.Content=new StringContent("<propfind xmlns=\"DAV:\"><prop><resourcetype/><getetag/><getlastmodified/></prop></propfind>",Encoding.UTF8,"application/xml");using var r=await http.SendAsync(q,ct);if(r.StatusCode==HttpStatusCode.Unauthorized)throw new Exception("Usuário ou senha inválidos.");if(!r.IsSuccessStatusCode&&(int)r.StatusCode!=207)throw new Exception($"PROPFIND HTTP {(int)r.StatusCode}");return XDocument.Parse(await r.Content.ReadAsStringAsync(ct));}IEnumerable<RemoteItem> Parse(XDocument doc,string requested){XNamespace d="DAV:";var req=Uri.UnescapeDataString(Url(requested).AbsolutePath).TrimEnd('/');var bp=Uri.UnescapeDataString(root.AbsolutePath).TrimEnd('/');foreach(var x in doc.Descendants(d+"response")){var href=Uri.UnescapeDataString(x.Element(d+"href")?.Value??"").TrimEnd('/');if(href.Equals(req,StringComparison.OrdinalIgnoreCase)||!href.StartsWith(bp,StringComparison.OrdinalIgnoreCase))continue;var rel=href[bp.Length..].Trim('/');if(rel.Length==0)continue;var p=x.Descendants(d+"prop").FirstOrDefault();var dir=p?.Element(d+"resourcetype")?.Element(d+"collection")!=null;DateTime? mod=DateTime.TryParse(p?.Element(d+"getlastmodified")?.Value,out var dt)?dt.ToUniversalTime():null;yield return new(rel,dir,mod,p?.Element(d+"getetag")?.Value);}}public async Task<List<string>> RootFolders(CancellationToken ct)=>Parse(await Prop("","1",ct),"").Where(x=>x.Directory).Select(x=>x.Path.Split('/')[0]).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x).ToList();public async Task<List<RemoteItem>> Items(IEnumerable<string> folders,bool syncAll,CancellationToken ct){var all=new Dictionary<string,RemoteItem>(StringComparer.OrdinalIgnoreCase);if(syncAll)await Walk("",all,ct);else foreach(var f in folders)await Walk(f,all,ct);return all.Values.Where(x=>!x.Path.Equals(".Trash",StringComparison.OrdinalIgnoreCase)&&!x.Path.StartsWith(".Trash/",StringComparison.OrdinalIgnoreCase)).ToList();}public async Task<List<RemoteItem>> Files(IEnumerable<string> folders,CancellationToken ct)=>(await Items(folders,false,ct)).Where(x=>!x.Directory).ToList();public async Task EnsureFolder(string folder,CancellationToken ct)=>await MakeFolders(folder.Replace('\\','/'),ct);async Task Walk(string folder,Dictionary<string,RemoteItem> all,CancellationToken ct){var items=Parse(await Prop(folder,"1",ct),folder).ToList();foreach(var i in items)all[i.Path]=i;foreach(var d in items.Where(x=>x.Directory))await Walk(d.Path,all,ct);}public async Task Download(string rel,string file,CancellationToken ct){using var r=await http.GetAsync(Url(rel,true),ct);r.EnsureSuccessStatusCode();Directory.CreateDirectory(Path.GetDirectoryName(file)!);var tmp=file+".meshsync-download";await using(var o=File.Create(tmp))await r.Content.CopyToAsync(o,ct);File.Move(tmp,file,true);}public async Task<string?> Upload(string rel,string file,string? etag,CancellationToken ct){await MakeFolders(Path.GetDirectoryName(rel.Replace('/','\\'))?.Replace('\\','/')??"",ct);using var q=new HttpRequestMessage(HttpMethod.Put,Url(rel,true));await using var input=File.OpenRead(file);q.Content=new StreamContent(input);if(etag!=null)q.Headers.TryAddWithoutValidation("If-Match",etag);using var r=await http.SendAsync(q,ct);if(r.StatusCode==HttpStatusCode.PreconditionFailed)throw new IOException("Conflito remoto.");r.EnsureSuccessStatusCode();return r.Headers.ETag?.Tag;}async Task MakeFolders(string folder,CancellationToken ct){var cur="";foreach(var p in folder.Split('/',StringSplitOptions.RemoveEmptyEntries)){cur=cur.Length==0?p:cur+"/"+p;using var r=await http.SendAsync(new HttpRequestMessage(new HttpMethod("MKCOL"),Url(cur,true)),ct);if(!r.IsSuccessStatusCode&&r.StatusCode!=HttpStatusCode.MethodNotAllowed&&r.StatusCode!=HttpStatusCode.Conflict)r.EnsureSuccessStatusCode();}}public async Task<string> MoveToTrash(string rel,CancellationToken ct){var n=rel.Replace('\\','/').Trim('/');var dest=".Trash/"+n;await MakeFolders(Path.GetDirectoryName(dest.Replace('/','\\'))?.Replace('\\','/')??".Trash",ct);if(await Exists(dest,ct)){var dir=Path.GetDirectoryName(dest.Replace('/','\\'))?.Replace('\\','/')??".Trash";var ext=Path.GetExtension(dest);var name=Path.GetFileNameWithoutExtension(dest);var i=1;string old;do{old=$"{dir}/{name} ({i++}){ext}";}while(await Exists(old,ct));await Move(dest,old,ct);}await Move(n,dest,ct);return dest;}async Task<bool> Exists(string p,CancellationToken ct){using var q=new HttpRequestMessage(HttpMethod.Head,Url(p,true));using var r=await http.SendAsync(q,ct);return r.IsSuccessStatusCode;}async Task Move(string from,string to,CancellationToken ct){using var q=new HttpRequestMessage(new HttpMethod("MOVE"),Url(from,true));q.Headers.TryAddWithoutValidation("Destination",Url(to,true).AbsoluteUri);q.Headers.TryAddWithoutValidation("Overwrite","F");using var r=await http.SendAsync(q,ct);if(!r.IsSuccessStatusCode)throw new Exception($"MOVE HTTP {(int)r.StatusCode}");}public void Dispose()=>http.Dispose();}
